from collections import Counter

def first_unique_fast(text):
    counts = Counter(text)            # one pass to count every character
    for i, ch in enumerate(text):     # one pass to find the first with count 1
        if counts[ch] == 1:
            return i
    return -1

tests = {"leetcode": 0, "loveleetcode": 2, "aabb": -1, "": -1, "z": 0}
for text, expected in tests.items():
    slow, fast = first_unique_slow(text), first_unique_fast(text)
    assert slow == fast == expected
    print(f"{text!r:>16} -> {fast:>2}   (expected {expected})")
